  return <Modal id="vault-modal" close={close}><h2>Vault</h2><div id="vault-body"><div className="vault-actions"><span className="vault-note">{secrets.length} secret(s). Values are never displayed.</span><button id="v-scan" className="icon" onClick={() => void action(async () => { setScan(await api.request('/secrets/scan')); })}>🔎 Scan notes</button><button id="v-lock" className="icon" onClick={() => void action(() => api.request('/vault/lock', { method: 'POST' }))}>🔒 Lock</button></div><Gate error={error} /><div id="v-list">{secrets.length ? secrets.map(s => { const d = details[s.name]; return <div className="v-row" key={s.name}><span>🔑 {s.name}<small className="pm"> {d?.status || ''} {d?.expires ? `· expires ${d.expires}` : ''} · {d?.uses || 0} uses · {d?.versions || 0} prior</small></span><span><button className="icon v-hist" onClick={() => void action(async () => { const r = await api.request<{ versions: { at?: string; note?: string }[] }>(`/secrets/versions?name=${encodeURIComponent(s.name)}`); setScan({ findings: r.versions.map((v, i) => ({ kind: `version ${i + 1}: ${v.note || 'unnamed'}`, masked: v.at })) }); })}>🕘</button><button className="icon danger v-del" onClick={() => confirm(`Delete ${s.name}?`) && void action(() => api.request(`/secrets/${encodeURIComponent(s.name)}`, { method: 'DELETE' }))}>🗑</button></span></div>; }) : <p className="vault-note">No secrets yet.</p>}</div><div className="ask-input-row"><input id="v-name" value={name} onChange={e => setName(e.target.value)} placeholder="name (for example github)" /><input id="v-val" type="password" value={value} onChange={e => setValue(e.target.value)} placeholder="value or token" /><button id="v-add" className="btn" disabled={!name || !value} onClick={() => void action(() => api.request('/secrets', { method: 'POST', body: { name, value } }))}>Add</button></div><section><h3>Scoped grant</h3><div className="ask-input-row"><select value={grant.secret} onChange={e => setGrant({ ...grant, secret: e.target.value })}><option value="">Secret</option>{secrets.map(s => <option key={s.name}>{s.name}</option>)}</select><input value={grant.grantee} onChange={e => setGrant({ ...grant, grantee: e.target.value })} placeholder="agent name" /><input value={grant.scope} onChange={e => setGrant({ ...grant, scope: e.target.value })} placeholder="scope (optional)" /><input type="number" value={grant.ttl} onChange={e => setGrant({ ...grant, ttl: e.target.value })} title="seconds" /><button disabled={!grant.secret || !grant.grantee} onClick={() => void action(() => api.request(`/secrets/${encodeURIComponent(grant.secret)}/grant`, { method: 'POST', body: { grantee: grant.grantee, scope: grant.scope, ttl_seconds: Number(grant.ttl) || 900, max_uses: Number(grant.max) || 0 } }))}>Grant</button></div></section>{grants.length > 0 && <section id="v-grants"><h3>Active grants</h3>{grants.map(g => <div className="v-row" key={g.token}><span>🎟 {g.grantee} → {g.secret} <small className="pm">{g.max_uses ? `${Math.max(0, g.max_uses - (g.uses || 0))} uses left` : 'time-limited'}</small></span><button className="icon danger v-revoke" onClick={() => void action(() => api.request(`/grants/${encodeURIComponent(g.token)}`, { method: 'DELETE' }))}>✕</button></div>)}</section>}{requests.length > 0 && <section><h3>Approval queue</h3>{requests.map(r => <div className="v-row" key={r.id}><span>{r.grantee} requests {r.secret}<small className="pm"> {r.reason || ''}</small></span><span><button className="gr-approve" onClick={() => void action(() => api.request(`/secrets/requests/${r.id}/approve`, { method: 'POST' }))}>Approve</button><button className="gr-deny" onClick={() => void action(() => api.request(`/secrets/requests/${r.id}/deny`, { method: 'POST', body: { note: 'Denied in console' } }))}>Deny</button></span></div>)}</section>}{scan && <section><h3>Credential scan / history metadata</h3><p className="vault-note">{scan.scanned !== undefined ? `Scanned ${scan.scanned} notes.` : ''}</p>{scan.findings?.map((f, i) => <div className="v-arow" key={i}><b>{f.confidence || ''} {f.kind}</b><span>{f.path}{f.line ? `:${f.line}` : ''}</span><code>{f.masked}</code></div>)}</section>}<details id="v-audit"><summary>Audit log ({audit.length})</summary>{audit.map((a, i) => <div className="v-arow" key={i}><span>{a.ts}</span><b>{a.action}</b><code>{a.secret}</code><span>{a.detail}</span></div>)}</details></div><button id="vault-close" onClick={close}>Close</button></Modal>;
