  const current = kinds.find(item => item.kind === kind);
  const load = useCallback(async () => { try { const [available, connectors] = await Promise.all([api.connectorKinds(), api.connectors()]); setKinds(available); setRows(connectors); setKind(previous => previous || available[0]?.kind || ''); } catch (e) { setError(e); setRows([]); } }, []); useEffect(() => { void load(); }, [load]);
  const freshValues = (source?: Connector) => { const formKind = kinds.find(k => k.kind === (source?.kind || kind)); if (!formKind) return; setKind(formKind.kind); setValues({ name: source?.name || formKind.name || '', prefix: source?.prefix || formKind.default_prefix || '', interval: String((source?.interval ?? 3600) / 60), secret: source?.secret || '', ...Object.fromEntries((formKind.fields || []).map(f => [f.name, source?.config?.[f.name] || ''])) }); };
  const begin = () => { freshValues(); setCreating(true); setEditing(undefined); };
  const edit = (row: Connector) => { freshValues(row); setCreating(false); setEditing(row); };
