  return <Modal id="inspect-modal" close={close}><h2 id="inspect-title">🔌 Connectors</h2><div id="inspect-body"><p className="vault-note">Connectors write pulled documents into the vault as ordinary notes. Their credentials stay in the vault by name.</p><Gate error={error} /><div id="conn-list">{rows.length ? rows.map(c => <div className="v-row conn-row" key={c.id}><span><b>{c.name}</b> <small className="pm">{c.kind} → {c.prefix}/ · {c.last_ok === false ? `failed: ${c.last_error || 'unknown error'}` : c.last_run ? `last run ${c.last_run}` : 'never run'}</small></span><span><button className="conn-run" onClick={() => void api.request(`/connectors/${c.id}/run`, { method: 'POST' }).then(load).catch(setError)}>Sync now</button><button className="conn-del icon danger" onClick={() => confirm('Remove this connector? Its notes are kept.') && void api.request(`/connectors/${c.id}`, { method: 'DELETE' }).then(load).catch(setError)}>✕</button></span></div>) : <p className="vault-note">Nothing configured yet.</p>}</div><h3>Add a connector</h3><select id="conn-kind" value={kind} onChange={e => setKind(e.target.value)}>{kinds.map(k => <option key={k.kind} value={k.kind}>{k.name || k.kind}</option>)}</select>{current && <div id="conn-form" className="conn-form"><p className="vault-note">{current.help}</p>{current.secret_help && <p className="vault-note"><b>Credential:</b> {current.secret_help}</p>}<label>Name<input id="cf-name" value={values.name || ''} onChange={e => setValues({ ...values, name: e.target.value })} /></label>{(current.fields || []).map(f => <label key={f.name}>{f.label || f.name}{f.required ? ' *' : ''}<input id={'cf-' + f.name} required={f.required} value={values[f.name] || ''} placeholder={f.placeholder} onChange={e => setValues({ ...values, [f.name]: e.target.value })} />{f.help && <small className="pm">{f.help}</small>}</label>)}{current.secret_help && <label>Vault credential name<input id="cf-secret" value={values.secret || ''} onChange={e => setValues({ ...values, secret: e.target.value })} placeholder="for example slack-token" /></label>}<label>Destination folder<input id="cf-prefix" value={values.prefix || ''} onChange={e => setValues({ ...values, prefix: e.target.value })} /></label><label>Sync every (minutes; 0 = manual)<input id="cf-interval" type="number" min="0" value={values.interval || '0'} onChange={e => setValues({ ...values, interval: e.target.value })} /></label><button id="cf-save" className="btn" onClick={() => void save()}>Save connector</button></div>}</div></Modal>;
