function CanvasPanel({ canvas, close, requestCard }: { canvas?: Canvas; close: () => void; requestCard: (x: number, y: number) => void }) {
  const [doc, setDoc] = useState(canvas); const [selected, setSelected] = useState<string>(); const [edgeTo, setEdgeTo] = useState(''); const [text, setText] = useState(''); const [file, setFile] = useState(''); const [zoom, setZoom] = useState(1); const [view, setView] = useState({ x: 0, y: 0 }); const [panning, setPanning] = useState(false); const [state, setState] = useState(''); const [error, setError] = useState('');
  useEffect(() => { setDoc(canvas); setSelected(undefined); setView({ x: 0, y: 0 }); if (canvas) setState('saved'); }, [canvas]);
  const persist = async (next: Canvas) => { setDoc(next); setState('saving…'); try { await api.request(`/canvas/${noteURLPath(next.path)}`, { method: 'PUT', body: { nodes: next.nodes, edges: next.edges } as unknown as JsonValue }); setState('saved'); } catch (e) { setError(e instanceof Error ? e.message : 'Save failed'); setState(''); } };
  const addCard = () => { if (!doc || !text.trim()) return; const n = { id: `n${Date.now().toString(36)}`, type: 'text', text: text.trim(), x: 60 + (doc.nodes.length % 4) * 230, y: 70 + Math.floor(doc.nodes.length / 4) * 120, width: 200, height: 80 }; setText(''); void persist({ ...doc, nodes: [...doc.nodes, n] }); };
  const remove = () => { if (!doc || !selected) return; void persist({ ...doc, nodes: doc.nodes.filter(n => n.id !== selected), edges: doc.edges.filter(e => e.fromNode !== selected && e.toNode !== selected) }); setSelected(undefined); };
  const addFile = () => { if (!doc || !file.trim()) return; const path = file.trim().endsWith('.md') ? file.trim() : `${file.trim()}.md`; setFile(''); void persist({ ...doc, nodes: [...doc.nodes, { id: `n${Date.now().toString(36)}`, type: 'file', file: path, x: 80, y: 80, width: 220, height: 60 }] }); };
  const link = () => { if (!doc || !selected || !edgeTo || edgeTo === selected) return; void persist({ ...doc, edges: [...doc.edges, { id: `e${Date.now().toString(36)}`, fromNode: selected, toNode: edgeTo }] }); setEdgeTo(''); };
  const move = (id: string, e: React.PointerEvent<HTMLDivElement>) => { if (!doc) return; e.stopPropagation(); e.currentTarget.setPointerCapture(e.pointerId); const node = doc.nodes.find(x => x.id === id); if (!node) return; const sx = e.clientX, sy = e.clientY, x = node.x, y = node.y; let latest = doc; const onMove = (ev: PointerEvent) => { latest = { ...doc, nodes: doc.nodes.map(v => v.id === id ? { ...v, x: x + (ev.clientX - sx) / zoom, y: y + (ev.clientY - sy) / zoom } : v) }; setDoc(latest); }; const onUp = () => { removeEventListener('pointermove', onMove); removeEventListener('pointerup', onUp); void persist(latest); }; addEventListener('pointermove', onMove); addEventListener('pointerup', onUp); };
  const pan = (e: React.PointerEvent<HTMLDivElement>) => { if ((e.target as HTMLElement).closest('.cv-node')) return; e.currentTarget.setPointerCapture(e.pointerId); const sx = e.clientX, sy = e.clientY, origin = view; setPanning(true); const onMove = (ev: PointerEvent) => setView({ x: origin.x + ev.clientX - sx, y: origin.y + ev.clientY - sy }); const onUp = () => { removeEventListener('pointermove', onMove); removeEventListener('pointerup', onUp); setPanning(false); }; addEventListener('pointermove', onMove); addEventListener('pointerup', onUp); };
  return <Modal id="canvas-view" close={close}><h2>Canvas <small id="cv-save">{state}</small></h2><div className="canvas-tools"><input value={text} onChange={e => setText(e.target.value)} onKeyDown={e => e.key === 'Enter' && addCard()} placeholder="Card text" /><button id="cv-add" onClick={addCard}>Add card</button><input value={file} onChange={e => setFile(e.target.value)} placeholder="Note path for file card" /><button onClick={addFile}>Add file card</button><select value={edgeTo} onChange={e => setEdgeTo(e.target.value)} disabled={!selected}><option value="">Connect selected to…</option>{doc?.nodes.filter(n => n.id !== selected).map(n => <option key={n.id} value={n.id}>{n.text || n.file}</option>)}</select><button onClick={link} disabled={!selected || !edgeTo}>Connect</button><button onClick={() => setZoom(z => Math.min(2, z + .2))}>+</button><button onClick={() => setZoom(z => Math.max(.4, z - .2))}>−</button><button onClick={() => setZoom(1)}>Reset zoom</button><button onClick={() => setView({ x: 0, y: 0 })}>Center view</button><button id="cv-delete" disabled={!selected} onClick={remove}>Delete selected</button></div><div className={'cv-viewport' + (panning ? ' panning' : '')} onPointerDown={pan} onDoubleClick={e => { if ((e.target as HTMLElement).closest('.cv-node')) return; const box = e.currentTarget.getBoundingClientRect(); requestCard((e.clientX - box.left - view.x) / zoom, (e.clientY - box.top - view.y) / zoom); }} onWheel={e => { e.preventDefault(); setZoom(z => Math.max(.4, Math.min(2, z * (e.deltaY < 0 ? 1.1 : .9)))); }}><svg className="cv-edges">{doc?.edges.map(e => { const a = doc.nodes.find(n => n.id === e.fromNode), b = doc.nodes.find(n => n.id === e.toNode); return a && b ? <line key={e.id} x1={view.x + (a.x + (a.width || 200) / 2) * zoom} y1={view.y + (a.y + 40) * zoom} x2={view.x + (b.x + (b.width || 200) / 2) * zoom} y2={view.y + (b.y + 40) * zoom} stroke="currentColor" /> : null; })}</svg>{doc?.nodes.map(n => <div className={'cv-node ' + (selected === n.id ? 'sel' : '')} data-node={n.id} key={n.id} style={{ position: 'absolute', left: view.x + n.x * zoom, top: view.y + n.y * zoom, width: (n.width || 200) * zoom }} onPointerDown={e => { setSelected(n.id); move(n.id, e); }} onDoubleClick={() => { if (n.type === 'file') { location.hash = encodeURIComponent(n.file || ''); return; } const changed = prompt('Card text', n.text || ''); if (changed !== null && doc) void persist({ ...doc, nodes: doc.nodes.map(v => v.id === n.id ? { ...v, text: changed } : v) }); }}>{n.text || n.file}</div>)}</div>{error && <p role="alert">{error}</p>}<button id="cv-close" onClick={close}>Close</button></Modal>;
}
function Login({ done }: { done: () => void }) { const [name, setName] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); return <main className="signin"><form id="signin-form" onSubmit={e => { e.preventDefault(); void api.login(name, password).then(done).catch((x: ApiError) => setError(x.message)); }}><h1>Sign in</h1><input id="signin-name" value={name} onChange={e => setName(e.target.value)} /><input id="signin-pass" type="password" value={password} onChange={e => setPassword(e.target.value)} /><button id="signin-go">Sign in</button><p id="signin-error">{error}</p></form></main>; }
